#!/usr/bin/env sh
# Prepares a development checkout: local secrets file and development databases.
# Safe to run several times: an existing passwords.yaml is never overwritten.
set -eu
cd "$(dirname "$0")/.."

secret() { openssl rand -base64 24 | tr '+/' '-_'; }

passwords=server/config/passwords.yaml
if [ ! -f "$passwords" ]; then
  cat > "$passwords" <<YAML
# Local development secrets — generated by tool/setup_dev.sh, never commit.
# Production secrets come from the .env file (see docker/.env.example).
development:
  database: 'owncoffer_dev'
  serviceSecret: '$(secret)'
  emailSecretHashPepper: '$(secret)'
  jwtHmacSha512PrivateKey: '$(secret)'
  jwtRefreshTokenHashPepper: '$(secret)'

test:
  database: 'owncoffer_test'
  serviceSecret: '$(secret)'
  emailSecretHashPepper: '$(secret)'
  jwtHmacSha512PrivateKey: '$(secret)'
  jwtRefreshTokenHashPepper: '$(secret)'
YAML
  echo "Created $passwords"
fi

docker compose -f docker/dev.compose.yaml up -d
